52	// writeItemHeader 输出事项的最新内容、严重程度、限制条件、后续负责人、
53	// 当前所在班次、关闭情况和流经班次。
54	func writeItemHeader(b *strings.Builder, it Item) {
55		state := "未关闭"
56		if it.Closed {
57			state = fmt.Sprintf("已关闭（%s 于 %s）", it.CloseOperator, fmtTimePtr(it.ClosedAt))
58		}
59		fmt.Fprintf(b, "%s  严重程度=%s  当前班次=%s  原始班次=%s  [%s]\n",
60			it.ID, it.Severity.Label(), it.CurrentShiftID, it.OriginShiftID, state)
61		fmt.Fprintf(b, "  内容：%s\n", it.Content)
62		fmt.Fprintf(b, "  限制条件：%s\n", dashIfEmpty(it.Constraints))
63		fmt.Fprintf(b, "  后续负责人：%s\n", it.FollowOwner)
64		fmt.Fprintf(b, "  流经班次：%s\n", strings.Join(it.ShiftIDs, " -> "))
65	}
66	
67	func dashIfEmpty(s string) string {
68		if s == "" {
69			return "-"
70		}
71		return s
72	}
73	
74	// whoIfRecorded 展示操作人，未记录时明确标为未记录，不以其他人代替。
75	func whoIfRecorded(s string) string {
76		if s == "" {
77			return "未记录"
78		}
79		return s
80	}
81	
82	// fmtTimePtrIfRecorded 展示时间指针，缺失时明确标为未记录。
83	func fmtTimePtrIfRecorded(t *time.Time) string {
84		if t == nil {
85			return "未记录"
86		}
87		return fmtTimeIfRecorded(*t)
88	}
89	
90	// fmtTimeIfRecorded 展示时间值，旧数据零值（0001-01-01T00:00:00Z）时
91	// 明确标为未记录，不显示公元元年日期。
92	func fmtTimeIfRecorded(t time.Time) string {
93		if t.IsZero() {
94			return "未记录"
95		}
96		return fmtTime(t)
97	}
98	
99	// fmtProcessedAtIfRecorded 展示处理时间，缺失（nil）或旧数据零值
100	// （0001-01-01T00:00:00Z）时明确标为未记录，不推测补齐。
101	func fmtProcessedAtIfRecorded(t *time.Time) string {
102		if t == nil || t.IsZero() {
103			return "未记录"
104		}
105		return fmtTime(*t)
106	}
107	
108	// entryCurrentResultLabel 是交接当前结果在事项处理经过查询中的展示名。
109	// 缺失或空结果显示“处理结果未记录”，无法识别的结果显示“处理结果无法识别”
110	// 并带出保存的原值，与交接清单、班次报告表达同一事实，不推测成已接收。
111	func entryCurrentResultLabel(s EntryStatus) string {
112		switch s {
113		case EntryPending:
114			return "待处理（接班人尚未处理）"
115		case EntryReturned:
116			return "退回（等待交班人补充）"
117		case EntryConfirmed:
118			return "确认接收"
119		case EntryTracking:
120			return "继续跟踪（已接收）"
121		case "":
122			return "处理结果未记录"
123		}
124		return "处理结果无法识别（原值：" + string(s) + "）"
125	}
126	
127	// FormatJourneyEvent 格式化处理经过中的单条记录。交接相关记录带有交接
128	// 编号与交班、接班班次；缺少的人名或时间明确标为未记录，不推测补齐。
129	func FormatJourneyEvent(ev JourneyEvent) string {
130		when := "未记录"
131		if ev.TimeKnown {
132			when = fmtTime(ev.At)
133		}
134		who := whoIfRecorded(ev.Operator)
135		where := ""
136		if ev.HandoverID != "" {
137			where = fmt.Sprintf("交接 %s（%s -> %s）", ev.HandoverID, ev.FromShift, ev.ToShift)
138		}
139		switch ev.Kind {
140		case "created":
141			return when + " 事项建立"
142		case "updated":
143			return fmt.Sprintf("%s 修改：%s", when, ev.Detail)
144		case "closed":
145			return fmt.Sprintf("%s 关闭 操作人=%s", when, who)
146		case "received":
147			return fmt.Sprintf("%s 接收 操作人=%s %s", when, who, ev.Detail)
148		case "handover-init":
149			// 交接发起不记录操作人，始终显示未记录，不以班次负责人代替。
150			return fmt.Sprintf("%s %s发起交接 操作人=%s", when, where, who)
151		case "return":
152			return fmt.Sprintf("%s %s第%d次退回 操作人=%s 原因=%s",
153				when, where, ev.RoundSeq, who, ev.Reason)
154		case "resubmit":
155			return fmt.Sprintf("%s %s第%d次重新提交 补充说明=%s 补充人=%s 补充时间=%s",
156				when, where, ev.RoundSeq, dashIfEmpty(ev.Supplement),
157				whoIfRecorded(ev.SupplementOperator), fmtTimePtrIfRecorded(ev.SupplementAt))
158		case "confirm":
159			return fmt.Sprintf("%s %s确认接收 操作人=%s", when, where, who)
160		case "track":
161			return fmt.Sprintf("%s %s继续跟踪 操作人=%s 跟踪说明=%s 后续负责人=%s",
162				when, where, who, dashIfEmpty(ev.TrackingNote), dashIfEmpty(ev.FollowOwner))
163		}
164		return when + " " + ev.Kind
165	}
166	
167	// FormatItemJourney 格式化凭事项编号查询得到的完整处理经过：开头为事项
168	// 最新状态，随后是合并事项自身历史与各次交接经过的时间线，最后列出该事项
169	// 在每次交接中的当前处理结果；尚未参与交接的显示暂无交接记录。
170	func FormatItemJourney(j ItemJourney) string {
171		var b strings.Builder
172		writeItemHeader(&b, j.Item)
173	
174		b.WriteString("  处理经过：\n")
175		if len(j.Events) == 0 {
176			b.WriteString("    （暂无记录）\n")
177		}
178		for _, ev := range j.Events {
179			b.WriteString("    - " + FormatJourneyEvent(ev) + "\n")
180		}
181	
182		b.WriteString("  交接当前结果：\n")
183		if !j.HasHandovers {
184			b.WriteString("    暂无交接记录\n")
185		}
186		for _, r := range j.Results {
187			operator, processedAt := "尚未处理", "尚未处理"
188			if r.Entry.Status != EntryPending {
189				// 已有处理结果（确认接收/继续跟踪/退回）时如实展示：处理人与
190				// 处理时间各自独立，缺失的明确标为未记录，不连带隐藏已保存的
191				// 处理人，也不把已处理结果显示成尚未处理。
192				operator = whoIfRecorded(r.Entry.Operator)
193				processedAt = fmtProcessedAtIfRecorded(r.Entry.ProcessedAt)
194			}
195			fmt.Fprintf(&b, "    交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
196				r.HandoverID, r.FromShift, r.ToShift,
197				entryCurrentResultLabel(r.Entry.Status), operator, processedAt)
198		}
199		return b.String()
200	}
201	
202	// FormatCloseItem 格式化班次结束时冻结的事项记录，并与最新状态对照。
203	func FormatCloseItem(snap CloseItemSnapshot, latest *Item) string {
204		var b strings.Builder
205		state := "结束时未关闭"
206		if snap.Closed {
207			state = fmt.Sprintf("结束时已关闭（%s 于 %s）", snap.CloseOperator, fmtTimePtr(snap.ClosedAt))
208		}
209		fmt.Fprintf(&b, "%s  严重程度=%s  %s\n", snap.ItemID, snap.Severity.Label(), state)
210		fmt.Fprintf(&b, "  内容：%s\n", snap.Content)
211		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(snap.Constraints))
212		fmt.Fprintf(&b, "  结束时后续负责人：%s\n", snap.FollowOwner)
213		if latest == nil {
214			b.WriteString("  最新状态：事项记录已不存在\n")
215			return b.String()
216		}
217		closeState := "未关闭"
218		if latest.Closed {
219			closeState = fmt.Sprintf("已关闭（%s 于 %s）", latest.CloseOperator, fmtTimePtr(latest.ClosedAt))
220		}
221		fmt.Fprintf(&b, "  最新状态：当前所在班次=%s  最新负责人=%s  最新关闭情况=%s\n",
222			latest.CurrentShiftID, latest.FollowOwner, closeState)
223		return b.String()
224	}
225	
226	// FormatOverlapNote 格式化重叠说明。
227	func FormatOverlapNote(n OverlapNote) string {
228		return fmt.Sprintf("%s  岗位=%s  班次 %s <-> %s  %s\n  说明：%s",
229			n.ID, n.Position, n.ShiftA, n.ShiftB, fmtTime(n.CreatedAt), n.Note)
230	}
231	
232	// FormatEntry 格式化交接单项当前结果与历次退回、补充说明。
233	func FormatEntry(e HandoverEntry) string {
234		var b strings.Builder
235		fmt.Fprintf(&b, "%s  [%s]  严重程度=%s  后续负责人=%s\n",
236			e.ItemID, e.Status.Label(), e.Severity.Label(), e.FollowOwner)
237		fmt.Fprintf(&b, "  原文：%s\n", e.Content)
238		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(e.Constraints))
239		// 是否处理过以已保存的处理结果为准，不以处理时间是否保存为准：确认接收、
240		// 继续跟踪与退回都属于已经发生的处理。处理人与处理时间各自独立展示，缺少
241		// 其中一个不能隐藏另一个：人名缺失明确标为未记录，时间缺失或为旧数据零值
242		// （0001-01-01T00:00:00Z）同样标为未记录，不以班次负责人、交接发起时间或
243		// 退回历史中的时间代替；真正待处理（含退回后已补充重新提交、等待接班人再次
244		// 处理）的事项才显示尚未处理。
245		if e.Status == EntryPending {
246			b.WriteString("  最后处理：尚未处理（等待接班人处理）；处理人=尚未处理；处理时间=尚未处理\n")
247		} else {
248			fmt.Fprintf(&b, "  最后处理：处理人=%s；处理时间=%s\n",
249				whoIfRecorded(e.Operator), fmtProcessedAtIfRecorded(e.ProcessedAt))
250		}
251		if e.Status == EntryTracking || e.TrackingNote != "" {
252			fmt.Fprintf(&b, "  跟踪说明：%s\n", dashIfEmpty(e.TrackingNote))
253			fmt.Fprintf(&b, "  跟踪后续负责人：%s\n", dashIfEmpty(e.FollowOwner))
254		}
255		for _, r := range e.Rounds {
256			fmt.Fprintf(&b, "  第%d次退回：%s 操作人=%s 原因=%s\n",
257				r.Seq, fmtTimeIfRecorded(r.ReturnedAt),
258				whoIfRecorded(r.ReturnOperator), r.Reason)
259			if r.Supplement != "" {
260				fmt.Fprintf(&b, "    补充说明：%s 补充人=%s 补充时间=%s\n",
261					r.Supplement, whoIfRecorded(r.SupplementOperator),
262					fmtTimePtrIfRecorded(r.SupplementAt))
263			}
264			if r.ResubmittedAt != nil {
265				fmt.Fprintf(&b, "    已重新提交：%s\n", fmtTimePtrIfRecorded(r.ResubmittedAt))
266			}
267		}
268		return b.String()
269	}
270	
271	// FormatHandover 格式化完整交接记录。
272	func FormatHandover(h Handover) string {
273		var b strings.Builder
274		state := "未完成"
275		if h.Completed() {
276			state = "已完成 " + fmtTimePtrIfRecorded(h.CompletedAt)
277		}
278		fmt.Fprintf(&b, "%s  岗位=%s  %s -> %s  发起于 %s  [%s]  共%d项\n",
279			h.ID, h.Position, h.FromShiftID, h.ToShiftID,
280			fmtTimeIfRecorded(h.CreatedAt), state, len(h.Entries))
281		if len(h.Entries) == 0 {
282			b.WriteString("  （空清单，直接完成）\n")
283		}
284		for i := range h.Entries {
285			b.WriteString(indentLines(FormatEntry(h.Entries[i]), "  "))
286		}
287		return b.String()
288	}
289	
290	func indentLines(s, prefix string) string {
291		return prefix + strings.ReplaceAll(strings.TrimRight(s, "\n"), "\n", "\n"+prefix) + "\n"
292	}
293	
294	// FormatReport 格式化按班次查询的完整报告。
295	func FormatReport(rep ShiftReport) string {
296		var b strings.Builder
297		b.WriteString("班次 " + FormatShift(rep.Shift) + "\n")
298	
299		b.WriteString("\n重叠说明：\n")
300		if len(rep.OverlapNotes) == 0 {
301			b.WriteString("  （无）\n")
302		}
303		for _, n := range rep.OverlapNotes {
304			b.WriteString(indentLines(FormatOverlapNote(n), "  "))
305		}
306	
307		if rep.ItemsAtClose {
308			b.WriteString("\n事项（以下为结束时记录，冻结于该班结束成功时刻；后班的修改、关闭与交接不改变本记录）：\n")
309			if len(rep.CloseItems) == 0 {
310				b.WriteString("  （结束时没有事项）\n")
311			}
312			for _, s := range rep.CloseItems {
313				var latest *Item
314				if v, ok := rep.LatestItems[s.ItemID]; ok {
315					latest = &v
316				}
317				b.WriteString(indentLines(FormatCloseItem(s, latest), "  "))
318			}
319		} else {
320			if rep.HistoryIncomplete {
321				b.WriteString("\n事项（历史记录不完整，该班结束时未留下记录，以下为当前信息，不能视为结束时事实）：\n")
322			} else {
323				b.WriteString("\n事项：\n")
324			}
325			if len(rep.Items) == 0 {
326				b.WriteString("  （无）\n")
327			}
328			for _, it := range rep.Items {
329				b.WriteString(indentLines(FormatItem(it), "  "))
330			}
331		}
332	
333		b.WriteString("\n交班对象：\n")
334		if rep.Outgoing == nil {
