1340		if eaBefore.Status != EntryReturned || len(eaBefore.Rounds) != 1 {
1341			t.Fatalf("前置状态应为退回且只有1轮：%+v", eaBefore)
1342		}
1343		if eaBefore.Operator != "李四" {
1344			t.Fatalf("前置处理人应为退回人李四")
1345		}
1346	
1347		// 即使填了操作人、退回原因、跟踪说明与后续负责人，也不能跳过重新提交。
1348		try := func(act EntryAction, reason, note, follow string) {
1349			t.Helper()
1350			if _, err := f.svc.ProcessEntry(h.ID, idA, act, "接班人王五", reason, note, follow); !errors.Is(err, ErrHandoverState) {
1351				t.Fatalf("退回未重新提交时 %s 应报 ErrHandoverState，got %v", act, err)
1352			}
1353		}
1354		try(ActionConfirm, "", "", "")
1355		try(ActionConfirm, "硬塞退回原因", "硬塞跟踪说明", "硬塞负责人")
1356		try(ActionTrack, "", "继续跟踪说明", "王五")
