// TestUncertainEntryResultKeepsHandoverIncomplete：清单中存在结果缺失或无法识别
// 的事项时，即使其他项已接收、记录里已有完成时间，交接也显示未完成；
// 缺失结果显示“处理结果未记录”，无法识别的结果显示“处理结果无法识别”并带出原值。
func TestUncertainEntryResultKeepsHandoverIncomplete(t *testing.T) {
	svc := openLegacyService(t, legacyUncertainResultRaw)

	h, err := svc.GetHandover("H001")
	if err != nil {
		t.Fatalf("get handover: %v", err)
	}
	if h.Completed() {
		t.Fatalf("存在结果缺失/无法识别事项时交接不应完成")
	}
	htext := FormatHandover(h)
	if !strings.Contains(htext, "未完成") || strings.Contains(htext, "已完成") {
		t.Fatalf("已有完成时间也不能显示成已完成：\n%s", htext)
	}
	if !strings.Contains(htext, "[确认接收]") {
		t.Fatalf("已确认项仍应显示确认接收：\n%s", htext)
	}
	if !strings.Contains(htext, "[处理结果未记录]") {
		t.Fatalf("缺失结果应显示处理结果未记录：\n%s", htext)
	}
	if !strings.Contains(htext, "处理结果无法识别（原值：archived）") {
		t.Fatalf("无法识别结果应显示处理结果无法识别并带出原值：\n%s", htext)
	}
}

// TestUncertainEntryResultBlocksShiftClose：接班班次收到的交接中存在结果缺失或
// 无法识别的事项时，结束班次明确失败，班次保持进行中，不写结束时间与结束时记录，
// 原交接结果、事项归属与处理经过不变；逐项处理修复后才能结束。
func TestUncertainEntryResultBlocksShiftClose(t *testing.T) {
	svc := openLegacyService(t, legacyUncertainResultRaw)
	svc.nowAt(func() time.Time { return tsDay(2, 20, 0) })

	snapshot := func() string {
		rep, err := svc.ShiftReport("S002")
		if err != nil {
			t.Fatalf("report: %v", err)
		}
		raw, err := json.Marshal(rep)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		return string(raw)
	}
	before := snapshot()

	if _, err := svc.CloseShift("S002"); !errors.Is(err, ErrHandoverState) {
		t.Fatalf("存在未确认接收事项时结束应报 ErrHandoverState，got %v", err)
	}
	sh, err := svc.GetShift("S002")
	if err != nil {
		t.Fatalf("get shift: %v", err)
	}
	if sh.Closed || sh.ClosedAt != nil || sh.CloseRecord != nil {
		t.Fatalf("结束失败应保持进行中，不写结束时间与结束时记录：%+v", sh)
	}
	if after := snapshot(); after != before {
		t.Fatalf("拒绝结束不得改变交接结果、事项归属与处理经过\nbefore %s\nafter  %s", before, after)
	}

	// 缺失结果与无法识别结果都可以按现有逐项处理功能明确接收。
	if _, err := svc.ProcessEntry("H001", "I002", ActionConfirm, "李四", "", "", ""); err != nil {
		t.Fatalf("处理结果缺失项应能确认接收：%v", err)
	}
	if _, err := svc.ProcessEntry("H001", "I003", ActionTrack, "李四", "", "继续跟进", "王五"); err != nil {
		t.Fatalf("无法识别结果项应能继续跟踪：%v", err)
	}
	h, err := svc.GetHandover("H001")
	if err != nil {
		t.Fatalf("get handover: %v", err)
	}
	// I001 是已明确接收的旧记录，缺少处理人与处理时间也仍算接收，不需要重新处理。
	if !h.Completed() || h.CompletedAt == nil {
		t.Fatalf("全部明确接收后交接应完成：%+v", h)
	}
	if _, err := svc.CloseShift("S002"); err != nil {
		t.Fatalf("全部明确接收后应能结束班次：%v", err)
	}
}

// TestUncertainResultConsistentAcrossQueries：交接查询、交班与接班两侧的班次报告、
// 事项处理经过对结果缺失/无法识别的事项表达同一事实，不展示成已确认，也不从事项
// 所在班次、处理人、处理时间或退回历史推测接收结果。
func TestUncertainResultConsistentAcrossQueries(t *testing.T) {
	svc := openLegacyService(t, legacyUncertainResultRaw)

	for _, shiftID := range []string{"S001", "S002"} {
		rep, err := svc.ShiftReport(shiftID)
		if err != nil {
			t.Fatalf("report %s: %v", shiftID, err)
		}
		rtext := FormatReport(rep)
		if !strings.Contains(rtext, "事项 I002 交接 H001（S001 -> S002）当前结果：处理结果未记录") {
			t.Fatalf("shift-show %s 应把缺失结果显示为处理结果未记录：\n%s", shiftID, rtext)
		}
		if !strings.Contains(rtext, "事项 I003 交接 H001（S001 -> S002）当前结果：处理结果无法识别（原值：archived）") {
			t.Fatalf("shift-show %s 应把无法识别结果显示原值：\n%s", shiftID, rtext)
		}
		if !strings.Contains(rtext, "[处理结果未记录]") || !strings.Contains(rtext, "处理结果无法识别（原值：archived）") {
			t.Fatalf("shift-show %s 嵌入的交接清单应与结果说明一致：\n%s", shiftID, rtext)
		}
		if strings.Contains(rtext, "I002 交接 H001（S001 -> S002）当前结果：确认接收") ||
			strings.Contains(rtext, "I003 交接 H001（S001 -> S002）当前结果：确认接收") {
			t.Fatalf("shift-show %s 不得把不确定结果展示成已确认：\n%s", shiftID, rtext)
		}
	}

	// 事项处理经过：不确定结果不产生接收事件，当前结果如实展示。
	j2, err := svc.ItemJourney("I002")
	if err != nil {
		t.Fatalf("journey I002: %v", err)
	}
	if got := journeyKinds(j2); joinStrings(got) != "created,handover-init" {
		t.Fatalf("结果缺失不应推测出接收事件：%v", got)
	}
	text2 := FormatItemJourney(j2)
	if !strings.Contains(text2, "当前结果：处理结果未记录") {
		t.Fatalf("item-show 应显示处理结果未记录：\n%s", text2)
	}
	if strings.Contains(text2, "确认接收") || strings.Contains(text2, "继续跟踪") {
		t.Fatalf("item-show 不得把缺失结果展示成已接收：\n%s", text2)
	}

	j3, err := svc.ItemJourney("I003")
	if err != nil {
		t.Fatalf("journey I003: %v", err)
	}
	if got := journeyKinds(j3); joinStrings(got) != "created,handover-init" {
		t.Fatalf("无法识别结果不应推测出接收事件：%v", got)
	}
	text3 := FormatItemJourney(j3)
	if !strings.Contains(text3, "当前结果：处理结果无法识别（原值：archived）") {
		t.Fatalf("item-show 应显示处理结果无法识别并带出原值：\n%s", text3)
	}
}

// TestUncertainResultInOneHandoverBlocksShiftClose：同一班次收到多条交接时，
// 其他交接全部完成也不能放行存在不确定结果的交接。
func TestUncertainResultInOneHandoverBlocksShiftClose(t *testing.T) {
	f := newFixture(t)
	a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 12, 0), "")
	b := mustShift(t, f, "调度", "李四", tsDay(2, 12, 0), tsDay(2, 16, 0), "")
	c := mustShift(t, f, "调度", "王五", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
	itA, err := f.svc.AddItem(a.ID, "甲班事项", SeverityNormal, "", "王五")
	if err != nil {
		t.Fatalf("add a: %v", err)
	}
	itB, err := f.svc.AddItem(b.ID, "乙班事项", SeverityNormal, "", "王五")
	if err != nil {
		t.Fatalf("add b: %v", err)
	}
	if _, err := f.svc.CloseShift(a.ID); err != nil {
		t.Fatalf("close a: %v", err)
	}
	if _, err := f.svc.CloseShift(b.ID); err != nil {
		t.Fatalf("close b: %v", err)
	}
	h1, err := f.svc.CreateHandover(a.ID, c.ID)
	if err != nil {
		t.Fatalf("handover a->c: %v", err)
	}
	h2, err := f.svc.CreateHandover(b.ID, c.ID)
	if err != nil {
		t.Fatalf("handover b->c: %v", err)
	}
	// h1 正常确认完成；h2 的清单被旧数据写成无法识别的结果。
	if _, err := f.svc.ProcessEntry(h1.ID, itA.ID, ActionConfirm, "王五", "", "", ""); err != nil {
		t.Fatalf("confirm h1: %v", err)
	}
	for i := range f.store.data.Handovers {
		if f.store.data.Handovers[i].ID == h2.ID {
			f.store.data.Handovers[i].Entries[0].Status = EntryStatus("archived")
		}
	}
	if got := mustGetHandover(t, f, h2.ID); got.Completed() {
		t.Fatalf("无法识别结果应使交接未完成")
	}

	if _, err := f.svc.CloseShift(c.ID); !errors.Is(err, ErrHandoverState) {
		t.Fatalf("其他交接已完成也不能放行不确定结果，got %v", err)
	}
	sh, _ := f.svc.GetShift(c.ID)
	if sh.Closed {
		t.Fatalf("班次应保持进行中")
	}

	// 明确接收后两条交接都完成，班次可以结束。
	if _, err := f.svc.ProcessEntry(h2.ID, itB.ID, ActionConfirm, "王五", "", "", ""); err != nil {
		t.Fatalf("修复不确定结果：%v", err)
	}
	if _, err := f.svc.CloseShift(c.ID); err != nil {
		t.Fatalf("全部交接完成后应能结束：%v", err)
	}
}

// Package handover 是本地班次交接与未关闭事项的本地基线。
package handover

// Ready 表示基线可以运行。
func Ready() bool { return true }

// Command handover 是本地班次交接与未关闭事项的命令行入口。
//
// 数据默认保存在当前目录 handover-data.json，可用全局参数 --data 或环境变量
// HANDOVER_DATA 指定。时间统一使用带时区偏移的 RFC3339，如
// 2026-10-02T08:00:00+08:00。
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	"github.com/bengzyyys/shift-handover/handover"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

const usageText = `用法：handover [--data 文件] <命令> [参数]

数据持久化在本地 JSON 文件中，退出后重新打开数据仍在。
时间使用带时区的 RFC3339，例如 2026-10-02T08:00:00+08:00。

班次：
  shift-add      建立班次        --position 岗位 --owner 负责人 --start 开始 --end 结束
                                 [--note 重叠说明（与同岗位已存班次区间重叠时必填）]
  shift-list     列出全部班次
  shift-close    结束班次        --id 班次编号
  shift-show     按班次查询      --id 班次编号（完整事项/交接/结果）

重叠说明：
  note-add       为重叠班次填说明 --a 班次 --b 班次 --note 说明
  note-list      查看班次涉及的重叠说明 --id 班次

事项：
  item-add       新增事项        --shift 班次 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-update    修改事项        --id 事项编号 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-close     关闭事项        --id 事项编号 --operator 操作人
  item-show      查询事项        --id 事项编号（最新状态、完整处理经过与各次交接当前结果）

交接：
  handover-create   发起交接      --from 交班班次 --to 接班班次
  handover-list     列出全部交接
  handover-show     查看交接      --id 交接编号
  handover-process  接班人处理单项 --id 交接编号 --item 事项编号 \
                                 --action confirm|return|track --operator 操作人 \
                                 [--reason 退回原因] [--note 跟踪说明] [--follow 后续负责人]
  handover-resubmit 交班人补充并重新提交退回项 \
                                 --id 交接编号 --item 事项编号 \
                                 --operator 操作人 --supplement 补充说明
`

func run(argv []string, stdout, stderr io.Writer) int {
	args := append([]string(nil), argv...)
	dataPath, rest := splitDataFlag(args, os.Getenv("HANDOVER_DATA"))
	if dataPath == "" {
		dataPath = "handover-data.json"
	}

	if len(rest) == 0 || rest[0] == "-h" || rest[0] == "--help" || rest[0] == "help" {
		fmt.Fprint(stdout, usageText)
		return 0
	}

	cmd, cmdArgs := rest[0], rest[1:]
	store, err := handover.Open(dataPath)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	svc := handover.NewService(store)

	out, err := dispatch(svc, cmd, cmdArgs)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	if out != "" {
		fmt.Fprint(stdout, out)
		if len(out) > 0 && out[len(out)-1] != '\n' {
			fmt.Fprintln(stdout)
		}
	}
	return 0
}

// valueFlags 是各子命令会带一个值的字符串参数。提取全局 --data 时，
// 这些参数后面的一个 token 是它的值：即使恰好写成 --data 或 --data=...，
// 也只是参数值（如事项内容、限制条件），不能当作数据文件参数取走。
var valueFlags = map[string]bool{
	"id": true, "position": true, "owner": true, "start": true, "end": true,
	"a": true, "b": true, "note": true, "shift": true, "content": true,
	"severity": true, "constraints": true, "follow": true, "operator": true,
	"from": true, "to": true, "item": true, "action": true, "reason": true,
	"supplement": true,
}

// splitDataFlag 从全部输入中抽出全局 --data（--data 路径 与 --data=路径 两种
// 形式，命令前后均可），返回数据文件路径与其余参数。已知参数的 --name value
// 形式中，value 原样保留，不参与 --data 判定；env 为未显式指定时的回退值。
func splitDataFlag(args []string, env string) (dataPath string, rest []string) {
	dataPath = env
	rest = make([]string, 0, len(args))
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if name, ok := flagName(arg); ok && name != "data" && valueFlags[name] {
			// 其他参数的 --name value 形式：下一个 token 是它的值，原样保留。
			rest = append(rest, arg)
			if i+1 < len(args) {
				rest = append(rest, args[i+1])
				i++
			}
			continue
		}
		switch {
		case arg == "--data" && i+1 < len(args):
			dataPath = args[i+1]
			i++
		case len(arg) > 7 && arg[:7] == "--data=":
			dataPath = arg[7:]
		default:
			rest = append(rest, arg)
		}
	}
	return dataPath, rest
}

// flagName 解析 -name / --name 形式的参数名；带 = 的形式值已内联，返回 false。
func flagName(arg string) (string, bool) {
	if !strings.HasPrefix(arg, "-") || strings.Contains(arg, "=") {
		return "", false
	}
	name := strings.TrimLeft(arg, "-")
	return name, name != ""
}

func dispatch(svc *handover.Service, cmd string, args []string) (string, error) {
	fs := flag.NewFlagSet(cmd, flag.ContinueOnError)
	fs.SetOutput(io.Discard)

	var (
		id, position, owner, startS, endS              string
		a, b                                           string
		shift, content, severityS, constraints, follow string
		operator, from, to                             string
		item, actionS, reason, note, supplement        string
	)
	fs.StringVar(&id, "id", "", "记录编号")
	fs.StringVar(&position, "position", "", "岗位")
	fs.StringVar(&owner, "owner", "", "负责人")
	fs.StringVar(&startS, "start", "", "开始时间 RFC3339")
	fs.StringVar(&endS, "end", "", "结束时间 RFC3339")
	fs.StringVar(&a, "a", "", "班次编号 A")
	fs.StringVar(&b, "b", "", "班次编号 B")
	// note-add 时为重叠说明；handover-process --action track 时为跟踪说明。
	fs.StringVar(&note, "note", "", "重叠说明 / 跟踪说明")
	fs.StringVar(&shift, "shift", "", "班次编号")
	fs.StringVar(&content, "content", "", "事项内容")
	fs.StringVar(&severityS, "severity", "", "严重程度 normal|important|urgent")
	fs.StringVar(&constraints, "constraints", "", "限制条件（可空）")
	// follow 同时用于后续负责人（新增/修改事项）与跟踪后续负责人（track）。
	fs.StringVar(&follow, "follow", "", "后续负责人")
	fs.StringVar(&operator, "operator", "", "操作人")
	fs.StringVar(&from, "from", "", "交班班次编号")
	fs.StringVar(&to, "to", "", "接班班次编号")
	fs.StringVar(&item, "item", "", "事项编号")
	fs.StringVar(&actionS, "action", "", "confirm|return|track")
	fs.StringVar(&reason, "reason", "", "退回原因")
	fs.StringVar(&supplement, "supplement", "", "补充说明")
	if err := fs.Parse(args); err != nil {
		return "", err
	}

	switch cmd {
	case "shift-add":
		start, err := parseTime("--start", startS)
		if err != nil {
			return "", err
		}
		end, err := parseTime("--end", endS)
		if err != nil {
			return "", err
		}
		sh, err := svc.CreateShift(position, owner, start, end, note)
		if err != nil {
			return "", err
		}
		return "已建立班次 " + handover.FormatShift(sh), nil

	case "shift-list":
		shifts := svc.ListShifts()
		if len(shifts) == 0 {
			return "（暂无班次）", nil
		}
		out := ""
		for _, sh := range shifts {
			out += handover.FormatShift(sh) + "\n"
		}
		return out, nil

	case "shift-close":
		sh, err := svc.CloseShift(id)
		if err != nil {
			return "", err
		}
		return "已结束班次 " + handover.FormatShift(sh), nil

	case "shift-show":
		rep, err := svc.ShiftReport(id)
		if err != nil {
			return "", err
		}
		return handover.FormatReport(rep), nil

	case "note-add":
		n, err := svc.AddOverlapNote(a, b, note)
		if err != nil {
			return "", err
		}
		return "已保存重叠说明 " + handover.FormatOverlapNote(n), nil

	case "note-list":
		notes := svc.OverlapNotes(id)
		if len(notes) == 0 {
			return "（无重叠说明）", nil
		}
		out := ""
		for _, n := range notes {
			out += handover.FormatOverlapNote(n) + "\n\n"
		}
		return out, nil

	case "item-add":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.AddItem(shift, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已新增事项\n" + handover.FormatItem(it), nil

	case "item-update":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.UpdateItem(id, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已修改事项\n" + handover.FormatItem(it), nil

	case "item-close":
		it, err := svc.CloseItem(id, operator)
		if err != nil {
			return "", err
		}
		return "已关闭事项\n" + handover.FormatItem(it), nil

	case "item-show":
		j, err := svc.ItemJourney(id)
		if err != nil {
			return "", err
		}
		return handover.FormatItemJourney(j), nil

	case "handover-create":
		h, err := svc.CreateHandover(from, to)
		if err != nil {
			if errors.Is(err, handover.ErrHandoverExists) {
				// 重复发起返回已有记录，不视为失败。
				return "已存在交接记录（重复发起，返回已有记录）\n" + handover.FormatHandover(h), nil
			}
			return "", err
		}
		return "已发起交接\n" + handover.FormatHandover(h), nil

	case "handover-list":
		hs := svc.ListHandovers()
		if len(hs) == 0 {
			return "（暂无交接记录）", nil
		}
		out := ""
		for _, h := range hs {
			out += handover.FormatHandover(h) + "\n"
		}
		return out, nil

	case "handover-show":
		h, err := svc.GetHandover(id)
		if err != nil {
			return "", err
		}
		return handover.FormatHandover(h), nil

	case "handover-process":
		action, err := handover.ParseAction(actionS)
		if err != nil {
			return "", err
		}
		h, err := svc.ProcessEntry(id, item, action, operator, reason, note, follow)
		if err != nil {
			return "", err
		}
		return "已处理\n" + handover.FormatHandover(h), nil

	case "handover-resubmit":
		h, err := svc.ResubmitReturned(id, item, operator, supplement)
		if err != nil {
			return "", err
		}
		return "已补充说明并重新提交\n" + handover.FormatHandover(h), nil

	default:
		return "", fmt.Errorf("未知命令 %q，运行 handover help 查看用法", cmd)
	}
}

func parseTime(name, s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, fmt.Errorf("%s 不能为空，格式为带时区的 RFC3339（如 2026-10-02T08:00:00+08:00）", name)
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, fmt.Errorf("%s 时间格式无效：%w（应为 RFC3339，如 2026-10-02T08:00:00+08:00）", name, err)
	}
	return t, nil
}

